import{_ as a,o as t,c as s,ag as o}from"./chunks/framework.7He2WLS4.js";const g=JSON.parse(`{"title":"DNS Mapping","description":"Override DNS resolution for specific domains with NectoProxy's custom DNS mapping.","frontmatter":{"title":"DNS Mapping","description":"Override DNS resolution for specific domains with NectoProxy's custom DNS mapping."},"headers":[],"relativePath":"features/dns-mapping.md","filePath":"features/dns-mapping.md","lastUpdated":1772297611000}`),n={name:"features/dns-mapping.md"};function i(r,e,p,d,l,c){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="dns-mapping" tabindex="-1">DNS Mapping <a class="header-anchor" href="#dns-mapping" aria-label="Permalink to &quot;DNS Mapping&quot;">​</a></h1><p>DNS Mapping lets you override DNS resolution for specific domains, directing traffic to custom IP addresses without modifying your system&#39;s hosts file or DNS settings. This is a powerful tool for development and testing workflows where you need to route traffic to alternative servers.</p><h2 id="what-is-dns-mapping" tabindex="-1">What is DNS Mapping? <a class="header-anchor" href="#what-is-dns-mapping" aria-label="Permalink to &quot;What is DNS Mapping?&quot;">​</a></h2><p>When NectoProxy receives a request for a domain, it normally resolves that domain using standard DNS to determine the server&#39;s IP address. DNS Mapping overrides this behavior for specific domains, telling NectoProxy to connect to a specific IP address instead of the DNS-resolved one.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Without DNS Mapping:</span></span>
<span class="line"><span>  Request for api.example.com</span></span>
<span class="line"><span>  --&gt; DNS resolves to 93.184.216.34 (production)</span></span>
<span class="line"><span>  --&gt; NectoProxy connects to 93.184.216.34</span></span>
<span class="line"><span></span></span>
<span class="line"><span>With DNS Mapping (api.example.com -&gt; 192.168.1.100):</span></span>
<span class="line"><span>  Request for api.example.com</span></span>
<span class="line"><span>  --&gt; DNS resolution is skipped</span></span>
<span class="line"><span>  --&gt; NectoProxy connects to 192.168.1.100 (local/staging)</span></span></code></pre></div><p>The client remains unaware of the mapping. From the client&#39;s perspective, it is communicating with <code>api.example.com</code> as usual. The TLS certificate presented by NectoProxy still matches <code>api.example.com</code> (since NectoProxy generates certificates for the requested hostname), and all request headers including the <code>Host</code> header remain unchanged.</p><div class="tip custom-block"><p class="custom-block-title">Key Advantage</p><p>Unlike editing the system hosts file, DNS Mapping in NectoProxy only affects traffic flowing through the proxy. Other applications on the same machine continue to use normal DNS resolution. This isolation prevents unexpected side effects and makes DNS Mapping safe to use in shared development environments.</p></div><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="testing-against-staging-servers" tabindex="-1">Testing Against Staging Servers <a class="header-anchor" href="#testing-against-staging-servers" aria-label="Permalink to &quot;Testing Against Staging Servers&quot;">​</a></h3><p>The most common use case is redirecting API calls from a production domain to a staging server:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.example.com  --&gt;  staging.internal.example.com (10.0.1.50)</span></span></code></pre></div><p>This lets you use a production build of your application (which makes requests to <code>api.example.com</code>) but have those requests served by your staging server. No code changes, no environment variable toggles, no separate builds.</p><h3 id="local-development" tabindex="-1">Local Development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local Development&quot;">​</a></h3><p>Redirect remote services to your local development machine:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.example.com     --&gt;  127.0.0.1</span></span>
<span class="line"><span>cdn.example.com     --&gt;  127.0.0.1</span></span>
<span class="line"><span>auth.example.com    --&gt;  127.0.0.1</span></span></code></pre></div><p>This is particularly useful when your application uses multiple microservices and you want to run one or more of them locally while keeping the rest connected to their remote endpoints.</p><h3 id="a-b-testing-across-backends" tabindex="-1">A/B Testing Across Backends <a class="header-anchor" href="#a-b-testing-across-backends" aria-label="Permalink to &quot;A/B Testing Across Backends&quot;">​</a></h3><p>Compare behavior between different backend versions by mapping domains to different servers during different test runs:</p><p><strong>Test A:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.example.com  --&gt;  10.0.1.50 (version 2.0)</span></span></code></pre></div><p><strong>Test B:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.example.com  --&gt;  10.0.1.51 (version 2.1-rc1)</span></span></code></pre></div><p>This approach lets you test your frontend against different backend versions without any deployment changes.</p><h3 id="accessing-services-by-ip" tabindex="-1">Accessing Services by IP <a class="header-anchor" href="#accessing-services-by-ip" aria-label="Permalink to &quot;Accessing Services by IP&quot;">​</a></h3><p>Some testing scenarios require connecting to a server by IP address, but the server application requires a specific <code>Host</code> header (e.g., virtual hosting). DNS Mapping allows the client to use the domain name (preserving the correct <code>Host</code> header) while NectoProxy connects to the desired IP.</p><h3 id="testing-disaster-recovery" tabindex="-1">Testing Disaster Recovery <a class="header-anchor" href="#testing-disaster-recovery" aria-label="Permalink to &quot;Testing Disaster Recovery&quot;">​</a></h3><p>Verify that your application works correctly when traffic is routed to a backup or disaster recovery server:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>api.example.com  --&gt;  10.0.2.100 (DR datacenter)</span></span></code></pre></div><h2 id="configuring-dns-mappings" tabindex="-1">Configuring DNS Mappings <a class="header-anchor" href="#configuring-dns-mappings" aria-label="Permalink to &quot;Configuring DNS Mappings&quot;">​</a></h2><h3 id="adding-a-mapping" tabindex="-1">Adding a Mapping <a class="header-anchor" href="#adding-a-mapping" aria-label="Permalink to &quot;Adding a Mapping&quot;">​</a></h3><ol><li>Open the <strong>DNS Mapping</strong> panel in the NectoProxy settings</li><li>Click <strong>Add Mapping</strong></li><li>Enter the <strong>domain name</strong> (or wildcard pattern)</li><li>Enter the <strong>target IP address</strong></li><li>Optionally add a <strong>description</strong> explaining the purpose of the mapping</li><li>The mapping is enabled by default</li></ol><h3 id="mapping-fields" tabindex="-1">Mapping Fields <a class="header-anchor" href="#mapping-fields" aria-label="Permalink to &quot;Mapping Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Domain</strong></td><td>Yes</td><td>The domain name to intercept (e.g., <code>api.example.com</code>)</td></tr><tr><td><strong>Target IP</strong></td><td>Yes</td><td>The IP address to connect to instead (e.g., <code>192.168.1.100</code>)</td></tr><tr><td><strong>Description</strong></td><td>No</td><td>A free-text note explaining the mapping&#39;s purpose</td></tr><tr><td><strong>Enabled</strong></td><td>--</td><td>Toggle to enable or disable the mapping</td></tr></tbody></table><h3 id="wildcard-domain-support" tabindex="-1">Wildcard Domain Support <a class="header-anchor" href="#wildcard-domain-support" aria-label="Permalink to &quot;Wildcard Domain Support&quot;">​</a></h3><p>DNS Mapping supports wildcard patterns for matching multiple subdomains:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Matches</th><th>Does Not Match</th></tr></thead><tbody><tr><td><code>api.example.com</code></td><td><code>api.example.com</code> only</td><td><code>www.example.com</code></td></tr><tr><td><code>*.example.com</code></td><td><code>api.example.com</code>, <code>www.example.com</code>, <code>cdn.example.com</code></td><td><code>example.com</code></td></tr><tr><td><code>*.api.example.com</code></td><td><code>v1.api.example.com</code>, <code>v2.api.example.com</code></td><td><code>api.example.com</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Wildcard mappings apply to all matching subdomains. Be cautious with broad wildcards like <code>*.example.com</code> as they will redirect all subdomain traffic, including services you may want to reach at their original destinations.</p></div><h3 id="enable-disable-per-mapping" tabindex="-1">Enable/Disable Per Mapping <a class="header-anchor" href="#enable-disable-per-mapping" aria-label="Permalink to &quot;Enable/Disable Per Mapping&quot;">​</a></h3><p>Each mapping has an <strong>enable/disable toggle</strong> that lets you quickly activate or deactivate it without deleting the configuration. This is useful when you need to temporarily switch between testing against a mapped server and the real server.</p><details class="details custom-block"><summary>Example Configuration</summary><table tabindex="0"><thead><tr><th>Domain</th><th>Target IP</th><th>Description</th><th>Enabled</th></tr></thead><tbody><tr><td><code>api.example.com</code></td><td><code>192.168.1.100</code></td><td>Local API server for development</td><td>Yes</td></tr><tr><td><code>cdn.example.com</code></td><td><code>127.0.0.1</code></td><td>Local CDN mock server</td><td>Yes</td></tr><tr><td><code>auth.example.com</code></td><td><code>10.0.1.50</code></td><td>Staging auth service</td><td>No</td></tr><tr><td><code>*.internal.corp</code></td><td><code>10.0.0.1</code></td><td>Corporate network gateway</td><td>Yes</td></tr></tbody></table></details><h2 id="managing-dns-mappings" tabindex="-1">Managing DNS Mappings <a class="header-anchor" href="#managing-dns-mappings" aria-label="Permalink to &quot;Managing DNS Mappings&quot;">​</a></h2><p>The DNS Mapping panel provides full <strong>CRUD operations</strong> through the Web UI:</p><h3 id="create" tabindex="-1">Create <a class="header-anchor" href="#create" aria-label="Permalink to &quot;Create&quot;">​</a></h3><p>Add new mappings through the Add Mapping form. Enter the domain, target IP, and optional description.</p><h3 id="read" tabindex="-1">Read <a class="header-anchor" href="#read" aria-label="Permalink to &quot;Read&quot;">​</a></h3><p>View all configured mappings in a table showing the domain, target IP, description, and enabled status.</p><h3 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h3><p>Click on any existing mapping to edit its domain, target IP, description, or enabled state.</p><h3 id="delete" tabindex="-1">Delete <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;Delete&quot;">​</a></h3><p>Remove mappings that are no longer needed. Deleted mappings are permanently removed and cannot be recovered.</p><h2 id="interaction-with-other-features" tabindex="-1">Interaction with Other Features <a class="header-anchor" href="#interaction-with-other-features" aria-label="Permalink to &quot;Interaction with Other Features&quot;">​</a></h2><h3 id="ssl-passthrough" tabindex="-1">SSL Passthrough <a class="header-anchor" href="#ssl-passthrough" aria-label="Permalink to &quot;SSL Passthrough&quot;">​</a></h3><p>DNS Mapping works <strong>alongside</strong> <a href="./ssl-passthrough.html">SSL Passthrough</a>. If a domain has both a DNS mapping and an SSL Passthrough entry, NectoProxy will:</p><ol><li>Resolve the domain using the DNS mapping (connecting to the specified IP)</li><li>Tunnel the traffic without decryption (as specified by SSL Passthrough)</li></ol><h3 id="rules-engine" tabindex="-1">Rules Engine <a class="header-anchor" href="#rules-engine" aria-label="Permalink to &quot;Rules Engine&quot;">​</a></h3><p><a href="./rules-engine.html">Rules Engine</a> rules are applied <strong>after</strong> DNS mapping. The request URL and <code>Host</code> header still reference the original domain, so URL-based rule matching works as expected.</p><h3 id="upstream-proxy" tabindex="-1">Upstream Proxy <a class="header-anchor" href="#upstream-proxy" aria-label="Permalink to &quot;Upstream Proxy&quot;">​</a></h3><p>If an <a href="./upstream-proxy.html">Upstream Proxy</a> is configured, DNS Mapping is applied <strong>before</strong> the request is forwarded to the upstream proxy. The upstream proxy receives the request with the mapped IP as the destination.</p><h2 id="practical-example-full-stack-local-development" tabindex="-1">Practical Example: Full-Stack Local Development <a class="header-anchor" href="#practical-example-full-stack-local-development" aria-label="Permalink to &quot;Practical Example: Full-Stack Local Development&quot;">​</a></h2><p>Consider a microservices architecture with the following production domains:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frontend.example.com    --&gt;  Production CDN</span></span>
<span class="line"><span>api.example.com         --&gt;  Production API gateway</span></span>
<span class="line"><span>auth.example.com        --&gt;  Production auth service</span></span>
<span class="line"><span>uploads.example.com     --&gt;  Production file storage</span></span></code></pre></div><p>During development, you want to run the API locally but keep other services pointing to production:</p><table tabindex="0"><thead><tr><th>Domain</th><th>Target IP</th><th>Description</th></tr></thead><tbody><tr><td><code>api.example.com</code></td><td><code>127.0.0.1</code></td><td>Local API running on port 8080</td></tr></tbody></table><p>Now your production frontend (served from <code>frontend.example.com</code>) makes API calls to <code>api.example.com</code>, which NectoProxy routes to your local machine. Auth and file upload services continue to use their production endpoints.</p><div class="tip custom-block"><p class="custom-block-title">Port Considerations</p><p>DNS Mapping changes only the IP address, not the port. If your local server runs on a non-standard port (e.g., 8080), the connection will still use the original port from the request URL (typically 443 for HTTPS or 80 for HTTP). Make sure your local server listens on the expected port, or use <a href="./rules-engine.html">Rules Engine Map Remote</a> to redirect to a different port.</p></div><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>DNS Mapping entries are persisted across NectoProxy sessions. Your mappings are saved automatically and restored when you restart the proxy.</p></div>`,67)])])}const m=a(n,[["render",i]]);export{g as __pageData,m as default};
